   163	function parseSseChunk(chunk: string): ReviewEventEnvelope[] {
   164	  const messages = chunk.split('\n\n');
   165	  const events: ReviewEventEnvelope[] = [];
   166	
   167	  for (const message of messages) {
   168	    const trimmed = message.trim();
   169	    if (!trimmed) {
   170	      continue;
   171	    }
   172	
   173	    let id: string | null = null;
   174	    const dataLines: string[] = [];
   175	    for (const line of trimmed.split('\n')) {
   176	      if (line.startsWith('id:')) {
   177	        id = line.slice(3).trim();
   178	        continue;
   179	      }
   180	      if (line.startsWith('data:')) {
   181	        dataLines.push(line.slice(5).trim());
   182	      }
   183	    }
   184	
   185	    if (dataLines.length === 0) {
   186	      continue;
   187	    }
   188	
   189	    const payload = dataLines.join('\n');
   190	    try {
   191	      events.push({
   192	        id,
   193	        data: JSON.parse(payload) as Record<string, unknown>,
   194	      });
   195	    } catch {
   196	      for (const dataLine of dataLines) {
   197	        events.push({
   198	          id,
   199	          data: JSON.parse(dataLine) as Record<string, unknown>,
   200	        });
   201	      }
   202	    }
   203	  }
   204	
   205	  return events;
   206	}
