import type { Env, ReviewContext, ReviewRunResponse } from '../../../types.js';
import { appendReviewEvent, getWorkspaceDeployment, getWorkspaceDeploymentRequestPayload } from '../../db.js';
import { runWorkspaceDeploymentAgentAnalysis } from '../../review-analysis.js';
import { asRecord, readOptionalString, resolveReviewAnalysisModel } from '../context-helpers.js';
import { loadAuthoritativeDeploymentDiff } from '../context-diff.js';
import { buildEvidence, buildHeuristicFindings } from '../report.js';
import type { ReviewRunExecutionOptions } from '../shared.js';
import { DEFAULT_REVIEW_ANALYSIS_TIMEOUT_MS, parseTimeoutMs, withTimeout } from './shared.js';

/**
 * Runs the optional model-backed analysis pass and returns agent output plus heuristic inputs.
 */
export async function runDeploymentReviewAnalysisStage(
  env: Env,
  review: ReviewRunResponse,
  payload: Record<string, unknown>,
  reviewContext: ReviewContext,
  inputs: {
    requestValidation: Record<string, unknown>;
    resultProvenance: Record<string, unknown>;
    resultArtifact: Record<string, unknown>;
    intentSessionContext: string[];
    derivedIntentSummary: unknown;
    promptGoal: string;
    promptConstraints: string[];
    promptDecisions: string[];
  },
  options?: ReviewRunExecutionOptions
) {
  const deployment = await getWorkspaceDeployment(env.DB, review.workspaceId, review.deploymentId);
  if (!deployment) {
    throw new Error(`Deployment not found for review target ${review.deploymentId}`);
  }

  const deploymentRequest = (await getWorkspaceDeploymentRequestPayload(env.DB, review.deploymentId)) ?? {};
  const deploymentEvents = await import('../../db.js').then((m) => m.listWorkspaceDeploymentEvents(env.DB, review.workspaceId, review.deploymentId, 0, 500));
  const heuristicFindings = buildHeuristicFindings(review, deploymentEvents);
  const analysisEvidence = buildEvidence(deploymentEvents, deployment, inputs.resultArtifact, true);
  const provenanceOperationId = typeof inputs.resultProvenance.operationId === 'string' ? inputs.resultProvenance.operationId : null;
  const reviewDiffArtifactId = typeof inputs.resultArtifact.reviewDiffArtifactId === 'string'
    ? inputs.resultArtifact.reviewDiffArtifactId
    : typeof inputs.resultProvenance.reviewDiffArtifactId === 'string'
      ? inputs.resultProvenance.reviewDiffArtifactId
      : null;
  const authoritativeDiff = await loadAuthoritativeDeploymentDiff(env, review.workspaceId, provenanceOperationId, reviewDiffArtifactId);
  const reviewAnalysisModel = resolveReviewAnalysisModel(payload, env);
  let agentAnalysis: Awaited<ReturnType<typeof runWorkspaceDeploymentAgentAnalysis>> = null;
  const reviewAgentEnabled = Boolean((env.AGENT_SDK_URL ?? '').trim());
  const deploymentSourceBundleKey =
    typeof inputs.resultArtifact.sourceBundleKey === 'string' && inputs.resultArtifact.sourceBundleKey.trim()
      ? inputs.resultArtifact.sourceBundleKey.trim()
      : deployment.sourceBundleKey ?? null;

  if (reviewAgentEnabled && deploymentSourceBundleKey) {
    await appendReviewEvent(env.DB, {
      reviewId: review.id,
      eventType: 'review_analysis_agent_started',
      payload: { provider: 'cloudflare_agents_sdk', model: reviewAnalysisModel },
    });

    const analysisTimeoutMs = parseTimeoutMs(env.REVIEW_ANALYSIS_TIMEOUT_MS, DEFAULT_REVIEW_ANALYSIS_TIMEOUT_MS);
    try {
      agentAnalysis = await withTimeout(
        runWorkspaceDeploymentAgentAnalysis(env, {
          reviewId: review.id,
          workspaceId: review.workspaceId,
          deploymentId: review.deploymentId,
          deploymentSandboxId: `review-snapshot-${review.id}`,
          sourceBundleKey: deploymentSourceBundleKey,
          modelOverride: reviewAnalysisModel,
          authoritativeDiffSnapshot: authoritativeDiff
            ? { source: authoritativeDiff.source, artifactId: authoritativeDiff.artifactId, patch: authoritativeDiff.patch }
            : undefined,
          goal: inputs.promptGoal,
          constraints: inputs.promptConstraints,
          decisions: inputs.promptDecisions.filter(Boolean),
          intentSessionContext: inputs.intentSessionContext,
          intentSummary: inputs.derivedIntentSummary as never,
          evidenceCatalog: analysisEvidence.map((item) => ({ id: item.id, type: item.type, label: item.label, status: item.status })),
          deploymentSummary: {
            provider: deployment.provider,
            deployedUrl: deployment.deployedUrl,
            validationSummary: JSON.stringify(inputs.requestValidation),
          },
          reviewContext,
          rootListing: {},
          diffSnapshot: {},
          onLifecycleEvent: async (eventType, eventPayload) => {
            await appendReviewEvent(env.DB, {
              reviewId: review.id,
              eventType,
              payload: eventPayload,
            });
          },
          openrouterApiKey: readOptionalString(options?.openrouterApiKey),
        }),
        analysisTimeoutMs,
        () => new Error(`Review analysis timed out after ${analysisTimeoutMs}ms while waiting for model/provider response`)
      );
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      if (/timed out|timeout/i.test(message)) {
        await appendReviewEvent(env.DB, {
          reviewId: review.id,
          eventType: 'review_analysis_timeout',
          payload: { timeoutMs: analysisTimeoutMs, message },
        });
      }
      throw error;
    }

    if (!agentAnalysis) {
      throw new Error('Review analysis did not produce output.');
    }
    if (agentAnalysis.validation.fallbackApplied) {
      throw new Error(`Review analysis produced non-authoritative fallback output (${agentAnalysis.validation.fallbackReason ?? 'unknown'}).`);
    }

    await appendReviewEvent(env.DB, {
      reviewId: review.id,
      eventType: 'review_analysis_agent_completed',
      payload: {
        provider: agentAnalysis.provider,
        model: agentAnalysis.model,
        stepsExecuted: agentAnalysis.stepsExecuted,
        findingCount: agentAnalysis.findings.length,
      },
    });
  }

  if (reviewAgentEnabled && !deploymentSourceBundleKey) {
    throw new Error('Deployment snapshot unavailable; review analysis cannot proceed without source bundle.');
  }
  if (reviewAgentEnabled && !agentAnalysis) {
    throw new Error('Review analysis did not produce output.');
  }

  return { deployment, deploymentRequest, deploymentEvents, heuristicFindings, analysisEvidence, agentAnalysis };
}

import type { ReviewAgentAction } from './tools.js';
import { asRecord, readOptionalString } from './helpers.js';
import {
  isMissingOpenRouterApiKeyError,
  isTimeoutLikeError,
  isWorkerToWorkerFetchRestriction,
  sanitizeErrorMessage,
  sleep,
} from './output.js';

const REVIEW_PROVIDER_TIMEOUT_MS = 120_000;
const REVIEW_PROVIDER_MAX_ATTEMPTS = 2;
const REVIEW_PROVIDER_RETRY_DELAY_MS = 750;

export type ReviewAgentHistoryEntry =
  | { role: 'assistant'; content: string }
  | { role: 'tool'; tool: string; output: unknown };

export interface ReviewAgentProvider {
  next(input: {
    prompt: string;
    model: string;
    maxSteps: number;
    step: number;
    history: ReviewAgentHistoryEntry[];
  }): Promise<ReviewAgentAction>;
}

export class CloudflareAgentSdkReviewProvider implements ReviewAgentProvider {
  constructor(
    private readonly endpoint: string,
    private readonly authToken: string | null,
    private readonly serviceBinding: Fetcher | null,
    private readonly openrouterApiKey: string | null,
    private readonly validateAction: (action: unknown) => ReviewAgentAction
  ) {}

  async next(input: {
    prompt: string;
    model: string;
    maxSteps: number;
    step: number;
    history: ReviewAgentHistoryEntry[];
  }): Promise<ReviewAgentAction> {
    const requestFetch = this.serviceBinding ? this.serviceBinding.fetch.bind(this.serviceBinding) : fetch;

    for (let attempt = 1; attempt <= REVIEW_PROVIDER_MAX_ATTEMPTS; attempt += 1) {
      const controller = new AbortController();
      let timeoutId: ReturnType<typeof setTimeout> | null = null;

      try {
        const requestPromise = requestFetch(this.endpoint, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            ...(this.authToken ? { Authorization: `Bearer ${this.authToken}` } : {}),
            ...(this.openrouterApiKey ? { 'X-Openrouter-Api-Key': this.openrouterApiKey } : {}),
          },
          body: JSON.stringify({
            mode: 'workspace_task',
            prompt: input.prompt,
            model: input.model,
            maxSteps: input.maxSteps,
            step: input.step,
            history: input.history,
          }),
          signal: controller.signal,
        });

        const timeoutPromise = new Promise<never>((_, reject) => {
          timeoutId = setTimeout(() => {
            controller.abort('review_provider_timeout');
            reject(new Error(`Review analysis provider request timed out after ${Math.floor(REVIEW_PROVIDER_TIMEOUT_MS / 1000)} seconds`));
          }, REVIEW_PROVIDER_TIMEOUT_MS);
        });

        const response = await Promise.race([requestPromise, timeoutPromise]);
        if (!response.ok) {
          const providerErrorBody = sanitizeErrorMessage(await response.text(), { openrouterApiKey: this.openrouterApiKey });
          if (isMissingOpenRouterApiKeyError(providerErrorBody)) {
            throw new Error(
              'Review analysis provider is missing an OpenRouter API key. Configure OPENROUTER_API_KEY for nimbus-agent-endpoint or pass X-Openrouter-Api-Key from the caller.'
            );
          }
          if (isWorkerToWorkerFetchRestriction(response.status, providerErrorBody)) {
            throw new Error(
              `Review analysis provider request blocked by Cloudflare Worker-to-Worker fetch restriction (error code 1042). Enable the 'global_fetch_strictly_public' compatibility flag on this worker or switch to a service binding.${providerErrorBody ? ` Provider response: ${providerErrorBody}` : ''}`
            );
          }

          const transientStatus = response.status >= 500 || response.status === 429;
          const statusError = new Error(
            transientStatus
              ? `Review analysis provider temporarily unavailable (status ${response.status})${providerErrorBody ? `: ${providerErrorBody}` : ''}`
              : `Review analysis provider request failed with status ${response.status}${providerErrorBody ? `: ${providerErrorBody}` : ''}`
          );

          if (transientStatus && attempt < REVIEW_PROVIDER_MAX_ATTEMPTS) {
            await sleep(REVIEW_PROVIDER_RETRY_DELAY_MS * attempt);
            continue;
          }

          throw statusError;
        }

        const parsed = (await response.json()) as unknown;
        const action = asRecord(parsed).action;
        return this.validateAction(action);
      } catch (error) {
        const timeoutLike = isTimeoutLikeError(error);
        const transientNetworkError = error instanceof Error && /fetch failed|network|connection reset|econnreset|socket hang up/i.test(error.message);
        if ((timeoutLike || transientNetworkError) && attempt < REVIEW_PROVIDER_MAX_ATTEMPTS) {
          await sleep(REVIEW_PROVIDER_RETRY_DELAY_MS * attempt);
          continue;
        }
        if (timeoutLike) {
          throw new Error(
            `Review analysis provider request timed out after ${Math.floor(REVIEW_PROVIDER_TIMEOUT_MS / 1000)} seconds (attempt ${attempt}/${REVIEW_PROVIDER_MAX_ATTEMPTS})`
          );
        }
        throw error;
      } finally {
        if (timeoutId !== null) {
          clearTimeout(timeoutId);
        }
      }
    }

    throw new Error('Review analysis provider exhausted retry attempts without a valid response');
  }
}

      await input.onLifecycleEvent('review_analysis_prompt_built', {
        reviewContextId: input.reviewContext.id,
      });
    }

    const provider = new CloudflareAgentSdkReviewProvider(
      endpoint,
      authToken,
      env.AGENT_ENDPOINT ?? null,
      readOptionalString(input.openrouterApiKey),
      validateReviewAgentAction
    );
    const policy: ReviewCommandPolicy = {
      commandAllow: [],
      commandDeny: ['git ', 'rm ', 'npm ', 'pnpm ', 'yarn ', 'bun ', 'mkdir ', 'mv ', 'cp ', 'touch '],
      maxCommandTimeoutMs: MAX_COMMAND_TIMEOUT_MS,
      maxOutputBytes: DEFAULT_REVIEW_MAX_OUTPUT_BYTES,
      rootPath: WORKSPACE_ROOT,
    };

    const history: ReviewAgentHistoryEntry[] = [];
    const usedTools: string[] = [];
    let finalValidationError: ReviewAgentOutputError | null = null;
    let repairAttempted = false;
    let repairSucceeded = false;
    let firstPassValid = false;
    let validationErrorCount = 0;
    let dedupedExactCount = 0;
    let fallbackApplied = false;
    let fallbackReason: string | null = null;

    for (let step = 1; step <= maxSteps; step += 1) {
      if (input.onLifecycleEvent) {
        await input.onLifecycleEvent('review_analysis_provider_request_started', {
          step,
          endpointHost,
          endpointPath,
          hasAuthToken: Boolean(authToken),
          hasOpenrouterApiKey: Boolean(readOptionalString(input.openrouterApiKey)),
        });
      }

      const action = await provider.next({ prompt, model, maxSteps, step, history });

      if (action.type === 'final') {
        if (input.onLifecycleEvent) {
          await input.onLifecycleEvent('review_analysis_model_output_received', { step, repairAttempted });
        }
        try {
          const parsed = parseJsonOutput(action.summary);
          const validated = validateOutputOrThrow(parsed);
          firstPassValid = !repairAttempted;
          repairSucceeded = repairAttempted;
          validationErrorCount = finalValidationError?.details && Array.isArray(finalValidationError.details.errors)
            ? finalValidationError.details.errors.length
            : 0;
          dedupedExactCount = validated.dedupedExactCount;
          if (repairAttempted && input.onLifecycleEvent) {
            await input.onLifecycleEvent('review_analysis_repair_output_received', { validationErrorCount, valid: true });
          }
          if (input.onLifecycleEvent) {
            await input.onLifecycleEvent('review_analysis_output_validated', {
              firstPassValid,
              repairAttempted,
              repairSucceeded,
              validationErrorCount,
              findingCount: validated.output.findings.length,
            });
          }
          return {
            findings: validated.output.findings,
            summary: validated.output.summary,
            furtherPassesLowYield: validated.output.furtherPassesLowYield,
            intent: null,
            provider: 'cloudflare_agents_sdk',
            model,
            stepsExecuted: step,
            usedTools,
            validation: {
              firstPassValid,
              repairAttempted,
              repairSucceeded,
              validationErrorCount,
              dedupedExactCount,
              fallbackApplied,
              fallbackReason,
            },
          };
        } catch (error) {
          if (error instanceof ReviewAgentOutputError && isGenericProviderCompletionSummary(action.summary)) {
            error = new ReviewAgentOutputError(
              'Review agent returned provider completion text instead of structured JSON; applying schema repair/fallback path'
            ).withCode('review_analysis_invalid_output', {
              errors: [{ path: '$', message: 'Provider completion summary returned instead of required JSON payload.' }],
            });
          }

          if (error instanceof ReviewAgentOutputError && !repairAttempted && step < maxSteps) {
            finalValidationError = error;
            repairAttempted = true;
            const validationErrors = extractValidationErrors(error);
            validationErrorCount = validationErrors.length;
            if (input.onLifecycleEvent) {
              await input.onLifecycleEvent('review_analysis_output_validation_failed', {
                errorCode: error.code,
                validationErrorCount,
                validationErrors,
              });
              await input.onLifecycleEvent('review_analysis_repair_requested', { validationErrorCount });
            }
            history.push({
              role: 'assistant',
              content: `final_output_validator: output failed schema; return corrected JSON only. Fix exactly these validation errors: ${JSON.stringify(validationErrors)}. Ensure summary is a plain string and furtherPassesLowYield is a JSON boolean true|false.`,
            });
            history.push({
              role: 'tool',
              tool: 'final_output_validator',
              output: {
                ok: false,
                error: 'Output must match ReviewAnalysisOutputV2 exactly.',
                requiredShape: {
                  findings: [{ severity: 'info|low|medium|high|critical', category: 'security|logic|style|breaking-change', passType: 'single', locations: [{ filePath: 'string', startLine: 'number|null', endLine: 'number|null' }], description: 'string', suggestedFix: 'string', failingScenario: 'string', evidence: 'string', guardGap: 'string' }],
                  summary: 'string',
                  furtherPassesLowYield: 'boolean',
                },
                validationErrors,
              },
            });
            continue;
          }

          if (error instanceof ReviewAgentOutputError && repairAttempted) {
            finalValidationError = error;
            const validationErrors = extractValidationErrors(error);
            validationErrorCount = validationErrors.length;
            if (input.onLifecycleEvent) {
              await input.onLifecycleEvent('review_analysis_repair_output_received', {
                validationErrorCount,
                valid: false,
                validationErrors,
              });
              await input.onLifecycleEvent('review_analysis_output_fallback_applied', {
                reason: 'invalid_after_repair',
                validationErrorCount,
                validationErrors,
              });
            }
            fallbackApplied = true;
            fallbackReason = 'invalid_after_repair';
            const fallback = buildFallbackAnalysisOutput(fallbackReason);
            return {
              findings: fallback.findings,
              summary: fallback.summary,
              furtherPassesLowYield: fallback.furtherPassesLowYield,
              intent: null,
              provider: 'cloudflare_agents_sdk',
              model,
              stepsExecuted: step,
              usedTools,
              validation: {
                firstPassValid: false,
                repairAttempted: true,
                repairSucceeded: false,
                validationErrorCount,
                dedupedExactCount,
                fallbackApplied,
                fallbackReason,
              },
            };
          }

          throw error;
        }
      }

      const output = await executeReviewTool(
        sandbox,
        action,
        policy,
        maxFileBytes,
        action.tool === 'diff_summary' ? input.authoritativeDiffSnapshot : undefined
      );
      usedTools.push(action.tool);
      history.push({ role: 'assistant', content: buildToolHistoryLabel(action) });
      history.push({ role: 'tool', tool: action.tool, output: sanitizeToolContext(output) });
    }

    if (finalValidationError) {
      throw finalValidationError;
    }
    throw new Error('Review analysis exceeded maximum step count');
  } finally {
    if (typeof sandbox.destroy === 'function') {
      try {
        await sandbox.destroy();
      } catch {
        // Best-effort cleanup only.
      }
    }
  }
}

