export async function handleGetReview(
  reviewId: string,
  request: Request,
  env: Env,
  authContext?: AuthContext
): Promise<Response> {
  const effectiveAuthContext =
    authContext ??
    ({ accountId: 'self-hosted', isAdmin: false, isAuthenticated: false, isHostedMode: false } as const);
  const reviewAccessResponse = await requireReviewAccess(env, reviewId, effectiveAuthContext);
  if (reviewAccessResponse) {
    return reviewAccessResponse;
  }

  let review = await getReviewRun(env.DB, reviewId);
  if (!review) {
    return jsonResponse({ error: 'Review not found' }, 404);
  }

  await recoverStaleRunningReviewIfNeeded(
    env,
    reviewId,
    review,
    readReviewGithubTokenHeader(request),
    readOpenrouterApiKeyHeader(request),
    { markFailedWhenRetryUnavailable: false, noAuthTerminalGraceMs: REVIEW_STALE_NOAUTH_TERMINAL_GRACE_MS }
  );
  review = await getReviewRun(env.DB, reviewId);
  if (!review) {
    return jsonResponse({ error: 'Review not found' }, 404);
  }

  return jsonResponse({ review });
}

export async function handleListReviews(
  request: Request,
  env: Env,
  authContext?: AuthContext
): Promise<Response> {
  const effectiveAuthContext =
    authContext ??
    ({ accountId: 'self-hosted', isAdmin: false, isAuthenticated: false, isHostedMode: false } as const);

  const url = new URL(request.url);
  const rawLimit = url.searchParams.get('limit');
  const parsedLimit = rawLimit ? Number.parseInt(rawLimit, 10) : Number.NaN;
  const limit = Number.isFinite(parsedLimit) && parsedLimit > 0 ? Math.min(parsedLimit, 200) : 100;

  const rawRepo = url.searchParams.get('repo');
  const rawBranch = url.searchParams.get('branch');
  const repo = rawRepo === null ? undefined : normalizeRepoSlug(rawRepo);
  const branch = rawBranch === null ? undefined : normalizeBranchRef(rawBranch);

  if (rawRepo !== null && !repo) {
    return jsonResponse(
      {
        error: 'Invalid repo query parameter. Expected owner/repo.',
        code: 'invalid_review_query',
      },
      400
    );
  }
  if (rawBranch !== null && !branch) {
    return jsonResponse(
      {
        error: 'Invalid branch query parameter.',
        code: 'invalid_review_query',
      },
      400
    );
  }

  const accountId =
    effectiveAuthContext.isHostedMode && !effectiveAuthContext.isAdmin
      ? effectiveAuthContext.isAuthenticated && typeof effectiveAuthContext.accountId === 'string'
        ? effectiveAuthContext.accountId
        : '__no_account__'
      : undefined;

  if (accountId === '__no_account__') {
    return jsonResponse({ reviews: [] });
  }

  const reviews = await listReviewRuns(env.DB, {
    limit,
    accountId,
    repo,
    branch,
  });

  return jsonResponse({ reviews });
}

export async function handleGetReviewEvents(
  reviewId: string,
  request: Request,
  env: Env,
  authContext?: AuthContext
): Promise<Response> {
  const effectiveAuthContext =
    authContext ??
    ({ accountId: 'self-hosted', isAdmin: false, isAuthenticated: false, isHostedMode: false } as const);
  try {
    const reviewAccessResponse = await requireReviewAccess(env, reviewId, effectiveAuthContext);
    if (reviewAccessResponse) {
      return reviewAccessResponse;
    }

    const review = await getReviewRun(env.DB, reviewId);
    if (!review) {
      return jsonResponse({ error: 'Review not found' }, 404);
    }

    const fromSeq = resolveFromSequence(request);
    const stream = createReviewEventsStream(env, reviewId, request, review.status, fromSeq);

    return new Response(stream, {
      status: 200,
      headers: {
        'Content-Type': 'text/event-stream',
        'Cache-Control': 'no-cache',
        Connection: 'keep-alive',
        ...corsHeaders,
      },
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    return jsonResponse({ error: message }, 500);
  }
}

import { appendReviewEvent, hasReviewEvent } from '../../lib/db.js';
import { createReviewQueueMessage } from '../../lib/review-queue.js';
import type { Env } from '../../types.js';
import { validateRecoveredReviewRetryAuth } from './recovery.js';
import { jsonResponse } from './shared.js';

interface QueueableReview {
  id: string;
  status: string;
  attemptCount: number;
  error?: { code?: string | null } | null;
}

export async function enqueueReviewRunIfNeeded(
  env: Env,
  review: QueueableReview,
  options: {
    reused: boolean;
    reviewGithubToken: string | null;
    openrouterApiKey: string | null;
  }
): Promise<Response | null> {
  if (review.status !== 'queued') {
    return null;
  }

  const alreadyEnqueued = await hasReviewEvent(env.DB, review.id, 'review_enqueued');
  const shouldReenqueueRecoveredReview =
    options.reused && (review.error?.code === 'retry_scheduled' || review.attemptCount > 0);
  const requiresOpenrouterRetryKey = review.error?.code === 'missing_openrouter_api_key';

  if (alreadyEnqueued && !shouldReenqueueRecoveredReview) {
    return null;
  }

  const authRetryError = await validateRecoveredReviewRetryAuth(
    env,
    review.id,
    shouldReenqueueRecoveredReview,
    options.reviewGithubToken
  );
  if (authRetryError) {
    return authRetryError;
  }

  if (shouldReenqueueRecoveredReview && requiresOpenrouterRetryKey && !options.openrouterApiKey) {
    return jsonResponse(
      {
        error: 'OpenRouter API key required for retry',
        code: 'missing_openrouter_api_key',
      },
      409
    );
  }

  await env.REVIEWS_QUEUE?.send(createReviewQueueMessage(review.id, options.reviewGithubToken, options.openrouterApiKey));
  await appendReviewEvent(env.DB, {
    reviewId: review.id,
    eventType: 'review_enqueued',
    payload: {
      mode: 'queue',
      reused: options.reused,
      recovered: shouldReenqueueRecoveredReview,
    },
  });

  return null;
}

export async function enqueueApprovedReviewRun(
  env: Env,
  reviewId: string,
  reviewGithubToken: string | null,
  openrouterApiKey: string | null
): Promise<void> {
  await env.REVIEWS_QUEUE?.send(createReviewQueueMessage(reviewId, reviewGithubToken, openrouterApiKey));
  await appendReviewEvent(env.DB, {
    reviewId,
    eventType: 'review_enqueued',
    payload: {
      mode: 'queue',
      policyApproved: true,
    },
  });
}

