  const effectiveMaxFileBytes =
    typeof input.maxFileBytes === 'number' && Number.isFinite(input.maxFileBytes)
      ? Math.max(1_024, Math.min(maxFileBytes, Math.floor(input.maxFileBytes)))
      : maxFileBytes;

