project_root = ${JSON.stringify(normalizedRoot)}
root_path = os.path.join(os.getcwd(), project_root) if project_root != '.' else os.getcwd()
package_json_path = os.path.join(root_path, 'package.json')
package_manager = None
scripts = {}
if os.path.exists(package_json_path):
    try:
        with open(package_json_path, 'r', encoding='utf-8') as f:
            parsed = json.load(f)
        if isinstance(parsed, dict):
            value = parsed.get('packageManager')
