            if isinstance(maybe_scripts, dict):
                scripts = maybe_scripts
    except Exception:
        scripts = {}

def lock_hash(name):
    path = os.path.join(root_path, name)
    if not os.path.exists(path):
        return None
    digest = hashlib.sha256()
    with open(path, 'rb') as f:
        while True:
            chunk = f.read(1024 * 128)
            if not chunk:
