    typeof policyModeFlag === 'string' && policyModeFlag.trim() ? normalizePolicyMode(policyModeFlag.trim()) : null;
  if (typeof policyModeFlag === 'string' && policyModeFlag.trim() && !canonicalPolicyMode) {
