  const patch = typeof record.patch === 'string' ? record.patch : null;
  if (!patch) {
    return value;
  }

  const clamped = clampText(patch, maxBytes);
  return {
    ...record,
    patch: clamped.text,
    truncated: clamped.truncated || Boolean(record.truncated),
  };
}

