          message: 'Complete action must include finalOutput or summary containing valid JSON payload.',
        },
      ],
    }
  );
}

function isSensitiveChangedPath(path: string): boolean {
  return /(?:recovery|retry|queue|status|state|workflow|db|auth)/i.test(path);
}

function buildSensitivePathReviewChecks(paths: string[]): string[] {
  const checks = new Set<string>();
  for (const path of paths) {
    if (/(?:recovery|retry|queue|status|state|workflow)/i.test(path)) {
      checks.add('Check running, queued, and terminal-state transitions separately; do not collapse them into one umbrella issue.');
