    setToastMessage(action === 'failed' ? 'Review failed cleanly' : 'Recovery requested');
    setRefreshCycle((value) => value + 1);
  } catch (error) {
    setRecoveryError(error instanceof Error ? error.message : String(error));
  } finally {
    setRecoveringReview(false);
  }
}, [reviewId]);

