export async function startStudioNewReview(options: {
  policyMode: StudioReviewPolicyMode;
  lastCheckpoints?: number;
  repoRoot?: string;
  expectedRepo?: string | null;
  expectedBranch?: string | null;
  signal?: AbortSignal;
  onEvent?: (event: StudioNewReviewStartStreamEvent) => void | Promise<void>;
}): Promise<StudioNewReviewStartResult> {
  let abortBeforeReviewCreation = true;
  const throwIfAborted = (): void => {
    if (!shouldAbortStudioStart(options.signal, abortBeforeReviewCreation)) {
      return;
    }
    const error = new Error('Studio review start aborted before completion.');
    error.name = 'AbortError';
    throw error;
  };
  const emitEvent = async (event: StudioNewReviewStartStreamEvent): Promise<void> => {
    throwIfAborted();
    try {
      await options.onEvent?.(event);
    } catch {
      // Start-flow events are best-effort only and must not abort review setup.
    }
  };

  throwIfAborted();
  const policyMode = normalizeStudioPolicyMode(options.policyMode);
  const lastCheckpoints = normalizeLastCheckpoints(options.lastCheckpoints ?? null);
  const repoRoot = resolveStudioRepoRoot(options.repoRoot);
  const workerUrl = getWorkerUrl();
  if (!workerUrl) {
    throw new Error('NIMBUS_WORKER_URL environment variable is required');
  }

  const gitProvenance = resolveReviewGitProvenance(repoRoot);
  if (
    !studioBranchContextMatchesExpected(gitProvenance, {
      repo: options.expectedRepo,
      branch: options.expectedBranch,
    })
  ) {
    throw new Error(
      `Studio context changed to ${gitProvenance.branch} (${gitProvenance.repo}). Switch context in Home, then retry.`
    );
  }

  await updateStudioPolicyMode(policyMode, { repoRoot });
  const resolved = await resolveReviewContext({
    commitish: 'HEAD',
    projectRoot: '.',
    lastCheckpoints,
    signal: options.signal,
    onProgress: (event) => emitEvent({
      type: 'stage',
      stage: event.stage,
      state: event.state,
      label: event.label,
      detail: event.detail,
    }),
  });

  await emitEvent({
    type: 'stage',
    stage: 'review_creation',
    state: 'active',
    label: policyMode === 'review' ? 'Creating policy review' : 'Creating review',
    detail:
      policyMode === 'review'
        ? 'Creating the review and opening the policy screen.'
        : 'Creating the review record before queueing analysis.',
  });

  if (policyMode === 'review') {
    throwIfAborted();
    const derived = await deriveReviewPolicy(workerUrl, {
      workspaceId: resolved.workspaceId,
      deploymentId: resolved.deploymentId,
      policyMode: 'review',
      reviewBasis: 'checkpoint',
      provenance: resolved.resolvedProvenance,
    });
    // Once the review exists, finish the handoff even if the client disconnects.
    abortBeforeReviewCreation = false;

    await emitEvent({
      type: 'stage',
      stage: 'review_creation',
      state: 'completed',
      label: 'Policy review ready',
      detail: `Review ${derived.reviewId} is ready for policy confirmation.`,
    });

    const result: StudioNewReviewStartResult = {
      reviewId: derived.reviewId,
      routePath: buildStudioReviewRoutePath({
        reviewId: derived.reviewId,
        route: 'policy',
        repo: resolved.resolvedProvenance.repo,
        branch: resolved.resolvedProvenance.branch,
      }),
      policyMode,
      status: 'policy_ready',
    };
    await emitEvent({
      type: 'completed',
      ...result,
      detail: 'Policy review is ready. Opening the policy screen.',
    });
    return result;
  }

  throwIfAborted();
  const derived = await deriveReviewPolicy(workerUrl, {
    workspaceId: resolved.workspaceId,
    deploymentId: resolved.deploymentId,
    policyMode: 'auto',
    reviewBasis: 'checkpoint',
    provenance: resolved.resolvedProvenance,
  });
  // Once the review exists, finish the handoff even if the client disconnects.
  abortBeforeReviewCreation = false;
  await emitEvent({
    type: 'stage',
    stage: 'review_creation',
    state: 'completed',
    label: 'Review created',
    detail: `Review ${derived.reviewId} was created and is ready to queue.`,
  });
  await emitEvent({
    type: 'stage',
    stage: 'policy',
    state: 'active',
    label: 'Approving policy',
    detail: 'Applying the derived policy so Nimbus can start analysis.',
  });
  await approveReviewPolicy(workerUrl, derived.reviewId, {
    approvedPolicy: derived.derivedPolicy,
  });
  await emitEvent({
    type: 'stage',
    stage: 'policy',
    state: 'completed',
    label: 'Review queued',
    detail: `Review ${derived.reviewId} is queued and ready to stream live activity.`,
  });

  const result: StudioNewReviewStartResult = {
    reviewId: derived.reviewId,
    routePath: buildStudioReviewRoutePath({
      reviewId: derived.reviewId,
      route: 'reports',
      repo: resolved.resolvedProvenance.repo,
      branch: resolved.resolvedProvenance.branch,
    }),
    policyMode,
    status: 'queued',
  };
  await emitEvent({
    type: 'completed',
    ...result,
    detail: 'Review queued. Opening the live results route.',
  });
  return result;
}

export function shouldAbortStudioStartForTests(
  signal: AbortSignal | undefined,
  abortBeforeReviewCreation: boolean
): boolean {
  return shouldAbortStudioStart(signal, abortBeforeReviewCreation);
}

export async function emitStudioStartEventForTests(input: {
  signal?: AbortSignal;
  onEvent?: (event: StudioNewReviewStartStreamEvent) => void | Promise<void>;
  event: StudioNewReviewStartStreamEvent;
}): Promise<void> {
  if (input.signal?.aborted) {
    const error = new Error('Studio review start aborted before completion.');
    error.name = 'AbortError';
    throw error;
  }
  try {
    await input.onEvent?.(input.event);
  } catch {
    // Best-effort only in tests as well.
  }
}

  const canRequeue = review.attemptCount <= maxRetries && Boolean(env.REVIEWS_QUEUE) && (scopedGithubToken || canRetryWithoutGithubToken);

  if (canRequeue) {
    await replaceReviewFindings(env.DB, reviewId, []);
    const message = 'Manual recovery requested while review was queued.';
    await updateReviewRunStatus(env.DB, reviewId, 'queued', {
      report: null,
      markdownSummary: null,
      startedAt: null,
      finishedAt: null,
      errorCode: 'retry_scheduled',
      errorMessage: message,
    });
    await appendReviewEvent(env.DB, {
      reviewId,
      eventType: 'review_retry_scheduled',
      payload: {
        attemptCount: review.attemptCount,
        maxRetries,
        reason: 'manual_recovery',
        priorStatus: review.status,
        authMode: scopedGithubToken ? 'scoped_request_token' : 'local_cochange_only',
      },
    });
    await env.REVIEWS_QUEUE?.send(createReviewQueueMessage(reviewId, scopedGithubToken, openrouterApiKey));
    return {
      action: 'requeued',
      review: await getReviewRun(env.DB, reviewId),
    };
  }

  const missingTokenSuffix =
    !scopedGithubToken && !canRetryWithoutGithubToken
      ? ' No retry was scheduled because a fresh scoped GitHub token was not provided.'
      : '';
  const retriesExhaustedSuffix = review.attemptCount > maxRetries ? ' No retry was scheduled because max retry attempts were exhausted.' : '';
  const message = `Manual recovery stopped this review after it appeared stuck in ${review.status} state.${missingTokenSuffix}${retriesExhaustedSuffix}`;
  await updateReviewRunStatus(env.DB, reviewId, 'failed', {
    report: null,
    markdownSummary: null,
    errorCode: 'review_execution_timeout',
    errorMessage: message,
  });
  await appendReviewEvent(env.DB, {
    reviewId,
    eventType: 'review_failed',
    payload: {
      code: 'review_execution_timeout',
      message,
      reason: 'manual_recovery',
    },
  });
  return {
    action: 'failed',
    review: await getReviewRun(env.DB, reviewId),
  };
}

export async function manuallyFailReviewRun(
  env: Env,
  reviewId: string
): Promise<{ action: 'failed'; review: Awaited<ReturnType<typeof getReviewRun>> }> {
  const review = await getReviewRun(env.DB, reviewId);
  if (!review) {
    return { action: 'failed', review: null };
  }

  if (review.status !== 'queued' && review.status !== 'running') {
    throw new Error(`Review is ${review.status}; only queued or running reviews can be failed manually.`);
  }

  const message =
    review.status === 'running'
      ? 'Review was manually marked failed while execution was still in progress. In-flight work may continue until the current attempt ends.'
      : 'Manual fail requested while review was queued.';

  await updateReviewRunStatus(env.DB, reviewId, 'failed', {
    report: null,
    markdownSummary: null,
    errorCode: 'review_execution_aborted',
    errorMessage: message,
  });
  await appendReviewEvent(env.DB, {
    reviewId,
    eventType: 'review_failed',
    payload: {
      code: 'review_execution_aborted',
      message,
      reason: 'manual_fail',
      priorStatus: review.status,
    },
  });

  return {
    action: 'failed',
    review: await getReviewRun(env.DB, reviewId),
  };
}

