function resolveStudioRepoRoot(explicitRepoRoot?: string): string {
  if (explicitRepoRoot?.trim()) {
    return explicitRepoRoot.trim();
  }
  try {
    return new GitRepo(process.cwd()).getRepoRoot();
  } catch {
    return process.cwd();
  }
}

function normalizeExpectedContextField(value: string | null | undefined): string | null {
  const normalized = value?.trim();
  return normalized ? normalized : null;
}

export function studioBranchContextMatchesExpected(
  current: { repo: string; branch: string },
  expected?: { repo?: string | null; branch?: string | null }
): boolean {
  const expectedRepo = normalizeExpectedContextField(expected?.repo);
  const expectedBranch = normalizeExpectedContextField(expected?.branch);
  if (!expectedRepo || !expectedBranch) {
    return true;
  }
  return current.repo === expectedRepo && current.branch === expectedBranch;
}

export async function resolveStudioNewReviewPreflight(options?: {
  repoRoot?: string;
  lastCheckpoints?: number;
}): Promise<StudioNewReviewPreflightResult> {
  const repoRoot = resolveStudioRepoRoot(options?.repoRoot);
  const lastCheckpoints = normalizeLastCheckpoints(options?.lastCheckpoints ?? null);
  const preferences = await readStudioPreferences({ repoRoot });
  const policyMode = normalizeStudioPolicyMode(preferences.policyMode);
  let repo: string | null = null;
  let branch: string | null = null;
  try {
    const gitProvenance = resolveReviewGitProvenance(repoRoot);
    repo = gitProvenance.repo;
    branch = gitProvenance.branch;
  } catch {
    repo = null;
    branch = null;
  }

  let commitSha: string | null = null;
  let checkpointId: string | null = null;
  let includedCheckpoints: Array<{ checkpointId: string; commitSha: string; commitSubject: string }> = [];
  let checkpointSelectionMode: 'latest' | 'last_n' = lastCheckpoints > 1 ? 'last_n' : 'latest';
  let checkpointDetail = '';
  try {
    const checkpoint = validateReviewCommitCheckpoint('HEAD', repoRoot, {
      lastCheckpoints,
    });
    commitSha = checkpoint.commitSha;
    checkpointId = checkpoint.checkpointId;
    includedCheckpoints = checkpoint.includedCheckpoints ?? [];
    checkpointSelectionMode = checkpoint.checkpointSelectionMode === 'last_n' ? 'last_n' : 'latest';
    checkpointDetail =
      checkpointSelectionMode === 'last_n'
        ? `Resolved ${includedCheckpoints.length} checkpoints ending at ${checkpointId}.`
        : `Resolved checkpoint ${checkpointId} from ${commitSha.slice(0, 12)}.`;
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    return {
      repo,
      branch,
      policyMode,
      lastCheckpoints,
      checkpointSelectionMode,
      checkpointId: null,
      commitSha: null,
      includedCheckpoints: [],
      ready: false,
      checks: [
        {
          code: 'checkpoint',
          label: 'Checkpoint target',
          ok: false,
          detail: message,
        },
        {
          code: 'entire_context',
          label: 'Entire context',
          ok: false,
          detail: 'Blocked until checkpoint target is available.',
        },
      ],
      error: {
        code: preflightErrorCode(message),
        message,
      },
    };
  }

  try {
    const context = await validateReviewEntireIntentContext(
      {
        commitSha,
        checkpointId,
      },
      {
        summarizeSession: 'auto',
        allowBranchFallback: true,
      },
      repoRoot
    );
    const contextDetail =
      context.contextResolution === 'branch_fallback'
        ? `Using branch fallback checkpoint ${context.resolvedCheckpointId} from ${context.commitsAgo} commit(s) ago.`
        : 'Readable Entire checkpoint context found for current commit.';
    return {
      repo,
      branch,
      policyMode,
      lastCheckpoints,
      checkpointSelectionMode,
      checkpointId,
      commitSha,
      includedCheckpoints,
      ready: true,
      checks: [
        {
          code: 'checkpoint',
          label: 'Checkpoint target',
          ok: true,
          detail: checkpointDetail,
        },
        {
          code: 'entire_context',
          label: 'Entire context',
          ok: true,
          detail: contextDetail,
        },
      ],
    };
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    return {
      repo,
      branch,
      policyMode,
      lastCheckpoints,
      checkpointSelectionMode,
      checkpointId,
      commitSha,
      includedCheckpoints,
      ready: false,
      checks: [
        {
          code: 'checkpoint',
          label: 'Checkpoint target',
          ok: true,
          detail: checkpointDetail,
        },
        {
          code: 'entire_context',
          label: 'Entire context',
          ok: false,
          detail: message,
        },
      ],
      error: {
        code: preflightErrorCode(message),
        message,
      },
    };
  }
}

export async function startStudioNewReview(options: {
  policyMode: StudioReviewPolicyMode;
  lastCheckpoints?: number;
  repoRoot?: string;
  expectedRepo?: string | null;
  expectedBranch?: string | null;
  signal?: AbortSignal;
  onEvent?: (event: StudioNewReviewStartStreamEvent) => void | Promise<void>;
}): Promise<StudioNewReviewStartResult> {
  let abortBeforeReviewCreation = true;
  const throwIfAborted = (): void => {
    if (!shouldAbortStudioStart(options.signal, abortBeforeReviewCreation)) {
      return;
    }
    const error = new Error('Studio review start aborted before completion.');
    error.name = 'AbortError';
    throw error;
  };
  const emitEvent = async (event: StudioNewReviewStartStreamEvent): Promise<void> => {
    throwIfAborted();
    try {
      await options.onEvent?.(event);
    } catch {
      // Start-flow events are best-effort only and must not abort review setup.
    }
  };

  throwIfAborted();
  const policyMode = normalizeStudioPolicyMode(options.policyMode);
  const lastCheckpoints = normalizeLastCheckpoints(options.lastCheckpoints ?? null);
  const repoRoot = resolveStudioRepoRoot(options.repoRoot);
  const workerUrl = getWorkerUrl();
  if (!workerUrl) {
    throw new Error('NIMBUS_WORKER_URL environment variable is required');
  }

  const gitProvenance = resolveReviewGitProvenance(repoRoot);
  if (
    !studioBranchContextMatchesExpected(gitProvenance, {
      repo: options.expectedRepo,
      branch: options.expectedBranch,
    })
  ) {
    throw new Error(
      `Studio context changed to ${gitProvenance.branch} (${gitProvenance.repo}). Switch context in Home, then retry.`
    );
  }

  await updateStudioPolicyMode(policyMode, { repoRoot });
  const resolved = await resolveReviewContext({
    commitish: 'HEAD',
    projectRoot: '.',
    lastCheckpoints,
    signal: options.signal,
    onProgress: (event) => emitEvent({
      type: 'stage',

          ? `Using fallback checkpoint ${entireContextResolution.resolvedCheckpointId} from ${entireContextResolution.commitsAgo} commit(s) ago.`
          : 'Readable Entire session metadata found for the current checkpoint.',
    });
    if (entireContextResolution.contextResolution === 'branch_fallback') {
      p.log.warning(
        `Using fallback Entire context from commit ${entireContextResolution.resolvedCommitSha.slice(0, 7)} ('${entireContextResolution.resolvedCommitSubject}') ${entireContextResolution.commitsAgo} commits ago.`
      );
    }
  } catch (error) {
    spinner.stop('Entire session metadata validation failed');
    throw buildReviewFlowStageError('checkpoint resolution', error);
  }

  spinner.start('Resolving local co-change context...');
  try {
    throwIfResolveReviewAborted(options);
    await emitResolveReviewProgress(options, {
      stage: 'cochange',
      state: 'active',
      label: 'Loading related context',
      detail: 'Collecting local co-change context and validating fallback readiness.',
    });
    localCochange = resolveLocalCochangeForCommitFlow(changedPaths, process.cwd(), {
      lookbackSessions: COCHANGE_LOOKBACK_SESSIONS,
      topN: COCHANGE_TOP_N,
    });
    if (localCochange) {
      spinner.stop(
        `Resolved local co-change context from ${localCochange.checkpointsRef} (${localCochange.sessionsScanned} sessions scanned)`
      );
    } else {
      spinner.stop('Local co-change context unavailable (worker will use GitHub fallback)');
    }
  } catch (error) {
    localCochange = null;
    const message = toErrorMessage(error);
    if (!isExpectedLocalCochangeResolutionError(message)) {
      p.log.warning(`Local co-change resolution error: ${message}`);
    }
    spinner.stop('Local co-change context unavailable (worker will use GitHub fallback)');
  }

  spinner.start('Checking co-change token readiness...');
  try {
    throwIfResolveReviewAborted(options);
    if (localCochange) {
      spinner.stop('Co-change token check skipped (using local co-change context)');
      await emitResolveReviewProgress(options, {
        stage: 'cochange',
        state: 'completed',
        label: 'Related context ready',
        detail: `Loaded local co-change context from ${localCochange.checkpointsRef} across ${localCochange.sessionsScanned} session(s).`,
      });
    } else {
      await validateReviewCochangeTokenReadiness();
      spinner.stop('Co-change token readiness confirmed');
      await emitResolveReviewProgress(options, {
        stage: 'cochange',
        state: 'completed',
        label: 'Related context ready',
        detail: 'Local co-change context was unavailable, so worker fallback is ready to use GitHub context.',
      });
    }
  } catch (error) {
    spinner.stop('Co-change token readiness check failed');
    throwIfResolveReviewAbortError(error);
    throw buildReviewFlowStageError('checkpoint resolution', error);
  }

  spinner.start('Creating workspace...');
  try {
    throwIfResolveReviewAborted(options);
    await emitResolveReviewProgress(options, {
      stage: 'workspace',
      state: 'active',
      label: 'Preparing workspace',
      detail: 'Creating an isolated workspace for the review target.',
    });
    throwIfResolveReviewAborted(options);
    const sourceResolved = resolveWorkspaceSourceForCommitFlow(commitSha, { projectRoot });
    const source = {
      ...sourceResolved,
      checkpointId,
    };
    const created = await createWorkspaceForCommitFlow(source);
    workspaceId = created.workspace.id;
    spinner.stop(`Workspace created: ${workspaceId}`);
    await emitResolveReviewProgress(options, {
      stage: 'workspace',
      state: 'completed',
      label: 'Workspace ready',
      detail: `Workspace ${workspaceId} created for the review target.`,
    });
  } catch (error) {
    spinner.stop('Workspace creation failed');
    throwIfResolveReviewAbortError(error);
    throw buildReviewFlowStageError('workspace creation', error);
  }

  spinner.start('Deploying workspace...');
  try {
    throwIfResolveReviewAborted(options);
    await emitResolveReviewProgress(options, {
      stage: 'deployment',
      state: 'active',
      label: 'Preparing deployment',
      detail: 'Deploying the workspace so Nimbus can run the review against the latest target.',
    });
    throwIfResolveReviewAborted(options);
    const deploymentIdempotencyKey = options?.idempotencyKey?.trim()
      ? deriveIdempotencyKey(options.idempotencyKey, 'deploy')
      : buildWorkspaceIdempotencyKey(commitSha);
    const deployment = await deployWorkspaceForCommitFlow(workspaceId, {
      idempotencyKey: deploymentIdempotencyKey,
      runTestsIfPresent: false,
      runBuildIfPresent: false,
      autoFix: false,
      pollIntervalMs: options?.pollIntervalMs,
      reporter: {
        message: (text) => spinner.message(text),
        success: (text) => spinner.message(text),
        warning: (text) => spinner.message(text),
        error: (text) => spinner.message(text),
      },
      entireIntentContextOverride: entireContextResolution ?? undefined,
    });
    if (!deployment) {
      throw new Error('Workspace deploy returned no deployment result.');
    }
    deploymentId = deployment.id;
    spinner.stop(`Deployment succeeded: ${deploymentId}`);
    await emitResolveReviewProgress(options, {
      stage: 'deployment',
      state: 'completed',
      label: 'Deployment ready',
      detail: `Deployment ${deploymentId} succeeded and is ready for review.`,
    });
  } catch (error) {
    spinner.stop('Workspace deploy failed');
    throwIfResolveReviewAbortError(error);
    throw buildReviewFlowStageError('workspace deploy', error);
  }

  const resolvedProvenance: ReviewCreateProvenance = {
    note: `Review with Entire checkpoint intent context (${entireContextResolution?.resolvedCheckpointId ?? checkpointId}).`,
    sessionIds: entireContextResolution?.context.sessionIds ?? [],
    intentSessionContext: entireContextResolution?.context.intentSessionContext ?? [],
    rawSessionPrompts: entireContextResolution?.context.rawSessionPrompts ?? null,
    commitSha,
    commitDiffPatch,
    commitDiffPatchSha256,
    commitDiffPatchTruncated,
    commitDiffPatchOriginalChars,
    contextResolution: entireContextResolution?.contextResolution ?? 'direct',
    contextResolutionOriginalCheckpointId: entireContextResolution?.originalCheckpointId ?? checkpointId,
    contextResolutionResolvedCheckpointId: entireContextResolution?.resolvedCheckpointId ?? checkpointId,
    contextResolutionResolvedCommitSha: entireContextResolution?.resolvedCommitSha ?? commitSha,
    contextResolutionResolvedCommitMessage: entireContextResolution?.resolvedCommitSubject,
    checkpointSelectionMode,
    includedCheckpoints,
    repo: gitProvenance.repo,
    branch: gitProvenance.branch,
    ...(options?.intentSummaryModel?.trim() ? { intentSummaryModel: options.intentSummaryModel.trim() } : {}),
    localCochange: localCochange
      ? {
          source: localCochange.source,
          checkpointsRef: localCochange.checkpointsRef,
          lookbackSessions: localCochange.lookbackSessions,
          topN: localCochange.topN,
          sessionsScanned: localCochange.sessionsScanned,
          relatedByChangedPath: localCochange.relatedByChangedPath,
        }
      : undefined,
  };

  return {
    workspaceId,
    deploymentId,
    resolvedProvenance,
  };
}

import { once } from 'events';
import type { IncomingMessage, ServerResponse } from 'http';
import { GitRepo } from '../../lib/checkpoint/git.js';
import { detectRepoSlugFromGitOrigin } from '../../lib/git.js';
import { startStudioNewReview } from './studio-create.js';
import { getStudioNewReviewPreflightCached } from './studio-preflight-cache.js';
import { createProxyHeaders } from './ui-events-fanout.js';

const LOCAL_HOST = '127.0.0.1';
const STUDIO_CONTEXT_PATH = '/api/studio/context';
const STUDIO_NEW_REVIEW_PREFLIGHT_PATH = '/api/studio/new-review/preflight';
const STUDIO_NEW_REVIEW_START_PATH = '/api/studio/new-review/start';
const STUDIO_NEW_REVIEW_START_EVENTS_PATH = '/api/studio/new-review/start/events';

let startStudioNewReviewForUiProxy: typeof startStudioNewReview = startStudioNewReview;

function parseLastCheckpoints(value: unknown): 1 | 2 | 3 {
  if (typeof value === 'number' && Number.isInteger(value) && value >= 1 && value <= 3) {
    return value as 1 | 2 | 3;
  }
  if (typeof value === 'string' && value.trim()) {
    const parsed = Number.parseInt(value.trim(), 10);
    if (Number.isInteger(parsed) && parsed >= 1 && parsed <= 3) {
      return parsed as 1 | 2 | 3;
    }
  }
  return 2;
}

function resolveRepoRootSafe(): string | undefined {
  try {
    return new GitRepo(process.cwd()).getRepoRoot();
  } catch {
    return undefined;
  }
}

async function readBody(request: IncomingMessage): Promise<Buffer> {
  const chunks: Buffer[] = [];
  for await (const chunk of request) {
    if (typeof chunk === 'string') {
      chunks.push(Buffer.from(chunk));
    } else {
      chunks.push(chunk);
    }
  }
  return Buffer.concat(chunks);
}

function writeSseFrame(response: ServerResponse, payload: unknown): void {
  response.write(`data: ${JSON.stringify(payload)}\n\n`);
}

export function setUiProxyHooksForTests(
  overrides: {
    startStudioNewReview?: typeof startStudioNewReview;
  } | null
): void {
  startStudioNewReviewForUiProxy = overrides?.startStudioNewReview ?? startStudioNewReview;
}

export async function proxyApiRequest(
  request: IncomingMessage,
  response: ServerResponse,
  workerUrl: string,
  apiKey: string | null,
  reviewGithubToken: string | null,
  openrouterApiKey: string | null
): Promise<boolean> {
  const requestUrl = new URL(request.url ?? '/', `http://${LOCAL_HOST}`);
  if (requestUrl.pathname === STUDIO_CONTEXT_PATH) {
    const method = (request.method ?? 'GET').toUpperCase();
    if (method !== 'GET' && method !== 'HEAD') {
      response.statusCode = 405;
      response.setHeader('Content-Type', 'application/json; charset=utf-8');
      response.end(JSON.stringify({ error: 'Method not allowed' }));
      return true;
    }

    let repo: string | null = null;
    let branch: string | null = null;
    try {
      repo = detectRepoSlugFromGitOrigin();
    } catch {
      repo = null;
    }
    try {
      branch = new GitRepo(process.cwd()).getCurrentBranchRef();
    } catch {
      branch = null;
    }

    const payload = {
      repo,
      branch,
      detectedAt: new Date().toISOString(),
    };
    response.statusCode = 200;
    response.setHeader('Content-Type', 'application/json; charset=utf-8');
    if (method === 'HEAD') {
      response.end();
      return true;
    }
    response.end(JSON.stringify(payload));
    return true;
  }

  if (requestUrl.pathname === STUDIO_NEW_REVIEW_PREFLIGHT_PATH) {
    const method = (request.method ?? 'GET').toUpperCase();
    if (method !== 'GET' && method !== 'HEAD') {
      response.statusCode = 405;
      response.setHeader('Content-Type', 'application/json; charset=utf-8');
      response.end(JSON.stringify({ error: 'Method not allowed' }));
      return true;
    }
    try {
      const payload = await getStudioNewReviewPreflightCached({
        repoRoot: resolveRepoRootSafe(),
        lastCheckpoints: parseLastCheckpoints(requestUrl.searchParams.get('lastCheckpoints')),
      });
      response.statusCode = 200;
      response.setHeader('Cache-Control', 'no-store');
      response.setHeader('Content-Type', 'application/json; charset=utf-8');
      if (method === 'HEAD') {
        response.end();
        return true;
      }
      response.end(JSON.stringify(payload));
      return true;
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      response.statusCode = 500;
      response.setHeader('Content-Type', 'application/json; charset=utf-8');
      response.end(JSON.stringify({ error: `Failed to load Studio preflight: ${message}` }));
      return true;
    }
  }

  if (requestUrl.pathname === STUDIO_NEW_REVIEW_START_PATH) {
    const method = (request.method ?? 'POST').toUpperCase();
    if (method !== 'POST') {
      response.statusCode = 405;
      response.setHeader('Content-Type', 'application/json; charset=utf-8');
      response.end(JSON.stringify({ error: 'Method not allowed' }));
      return true;
    }
    try {
      const body = await readBody(request);
      const payload = JSON.parse(body.toString('utf8')) as {
        policyMode?: unknown;
        repo?: unknown;
        branch?: unknown;
        lastCheckpoints?: unknown;
      };
      const policyMode = payload?.policyMode;
      if (policyMode !== 'auto' && policyMode !== 'review') {
        response.statusCode = 400;
        response.setHeader('Content-Type', 'application/json; charset=utf-8');
        response.end(JSON.stringify({ error: 'Invalid policyMode. Use auto or review.' }));
        return true;
      }

      const expectedRepo = typeof payload.repo === 'string' ? payload.repo : null;
      const expectedBranch = typeof payload.branch === 'string' ? payload.branch : null;
      const started = await startStudioNewReviewForUiProxy({
        policyMode,
        lastCheckpoints: parseLastCheckpoints(payload.lastCheckpoints),
        repoRoot: resolveRepoRootSafe(),
        expectedRepo,
        expectedBranch,
      });
      response.statusCode = 200;
      response.setHeader('Content-Type', 'application/json; charset=utf-8');
      response.end(JSON.stringify(started));
      return true;
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      response.statusCode = 500;
      response.setHeader('Content-Type', 'application/json; charset=utf-8');
      response.end(JSON.stringify({ error: `Failed to start review: ${message}` }));
      return true;
    }
  }

  if (requestUrl.pathname === STUDIO_NEW_REVIEW_START_EVENTS_PATH) {
    const method = (request.method ?? 'GET').toUpperCase();
    if (method !== 'GET') {
      response.statusCode = 405;
      response.setHeader('Content-Type', 'application/json; charset=utf-8');
      response.end(JSON.stringify({ error: 'Method not allowed' }));
      return true;
    }

    const policyMode = requestUrl.searchParams.get('policyMode');
    if (policyMode !== 'auto' && policyMode !== 'review') {
      response.statusCode = 400;
      response.setHeader('Content-Type', 'application/json; charset=utf-8');
      response.end(JSON.stringify({ error: 'Invalid policyMode. Use auto or review.' }));
      return true;
    }

    const expectedRepo = requestUrl.searchParams.get('repo');
    const expectedBranch = requestUrl.searchParams.get('branch');
    const lastCheckpoints = parseLastCheckpoints(requestUrl.searchParams.get('lastCheckpoints'));
    let streamOpen = true;
    const abortController = new AbortController();
    response.on('close', () => {
      streamOpen = false;
      abortController.abort();
    });
    response.statusCode = 200;
    response.setHeader('Cache-Control', 'no-store');
    response.setHeader('Connection', 'keep-alive');
    response.setHeader('Content-Type', 'text/event-stream; charset=utf-8');
    response.flushHeaders?.();

    try {
      await startStudioNewReviewForUiProxy({
        policyMode,
        lastCheckpoints,
        repoRoot: resolveRepoRootSafe(),
        expectedRepo,
        expectedBranch,
        signal: abortController.signal,
        onEvent: async (event) => {
          if (!streamOpen || abortController.signal.aborted) {
            return;
          }
          try {
            writeSseFrame(response, event);
          } catch {
            streamOpen = false;
            abortController.abort();
          }
        },
      });
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      if (streamOpen) {
        writeSseFrame(response, {
          type: 'error',
          message: `Failed to start review: ${message}`,
        });
      }
    } finally {
      if (streamOpen) {
        response.end();
      }
    }
    return true;
  }

  if (!(requestUrl.pathname === '/api' || requestUrl.pathname.startsWith('/api/'))) {
    return false;
  }

  const targetUrl = new URL(`${requestUrl.pathname}${requestUrl.search}`, workerUrl);
  const method = (request.method ?? 'GET').toUpperCase();
  const headers = createProxyHeaders(request.headers, {
    apiKey,
    reviewGithubToken,
    openrouterApiKey,
  });

  const body = method === 'GET' || method === 'HEAD' ? undefined : new Uint8Array(await readBody(request));
  const upstream = await fetch(targetUrl.toString(), {
    method,
    headers,
    body,
  });

  response.statusCode = upstream.status;
  response.statusMessage = upstream.statusText;
  upstream.headers.forEach((value, key) => {
    if (key.toLowerCase() === 'transfer-encoding') {
      return;
    }
    response.setHeader(key, value);
  });

  if (!upstream.body || method === 'HEAD') {
    response.end();
    return true;
  }

  const reader = upstream.body.getReader();
  while (true) {
    const { done, value } = await reader.read();
    if (done) {
      break;
    }
    if (!value || value.byteLength === 0) {
      continue;
    }
    if (!response.write(Buffer.from(value))) {
      await once(response, 'drain');
    }
  }
  response.end();
  return true;
}

