    .join('\n\n---\n\n');

  return {
    context: {
      note: `Review context merged from ${input.includedCheckpoints.length} checkpoints (${input.includedCheckpoints
        .map((entry) => entry.checkpointId)
        .join(' -> ')}).`,
      sessionIds,
