export class CloudflareAgentSdkReviewProvider implements ReviewAgentProvider {
  constructor(
    private readonly endpoint: string,
    private readonly authToken: string | null,
    private readonly serviceBinding: Fetcher | null,
    private readonly openrouterApiKey: string | null,
    private readonly validateAction: (action: unknown) => ReviewAgentAction
  ) {}

  async next(input: {
    prompt: string;
    model: string;
    reasoningEffort?: 'minimal' | 'low' | 'medium' | 'high';
    maxSteps: number;
    step: number;
    history: ReviewAgentHistoryEntry[];
    forceComplete?: boolean;
    abortSignal?: AbortSignal;
  }): Promise<ReviewAgentAction> {
    const requestFetch = this.serviceBinding ? this.serviceBinding.fetch.bind(this.serviceBinding) : fetch;

    for (let attempt = 1; attempt <= REVIEW_PROVIDER_MAX_ATTEMPTS; attempt += 1) {
      const controller = new AbortController();
      let timeoutId: ReturnType<typeof setTimeout> | null = null;
      const handleExternalAbort = (): void => {
        controller.abort();
      };

      try {
        if (input.abortSignal?.aborted) {
          throw buildProviderAbortError();
        }
        input.abortSignal?.addEventListener('abort', handleExternalAbort, { once: true });
        const requestPromise = requestFetch(this.endpoint, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            ...(this.authToken ? { Authorization: `Bearer ${this.authToken}` } : {}),
            ...(this.openrouterApiKey ? { 'X-Openrouter-Api-Key': this.openrouterApiKey } : {}),
          },
          body: JSON.stringify({
            mode: 'workspace_task',
            prompt: input.prompt,
            model: input.model,
            ...(input.reasoningEffort ? { reasoningEffort: input.reasoningEffort } : {}),
            maxSteps: input.maxSteps,
            step: input.step,
            history: input.history,
            ...(input.forceComplete === true ? { forceComplete: true } : {}),
          }),
          signal: controller.signal,
        });

        const timeoutPromise = new Promise<never>((_, reject) => {
          timeoutId = setTimeout(() => {
            controller.abort('review_provider_timeout');
            reject(new Error(`Review analysis provider request timed out after ${Math.floor(REVIEW_PROVIDER_TIMEOUT_MS / 1000)} seconds`));
          }, REVIEW_PROVIDER_TIMEOUT_MS);
        });

        const response = await Promise.race([requestPromise, timeoutPromise]);
        if (!response.ok) {
          const providerErrorBody = sanitizeErrorMessage(await response.text(), { openrouterApiKey: this.openrouterApiKey });
          if (isMissingOpenRouterApiKeyError(providerErrorBody)) {
            throw new Error(
              'Review analysis provider is missing an OpenRouter API key. Configure OPENROUTER_API_KEY for nimbus-agent-endpoint or pass X-Openrouter-Api-Key from the caller.'
            );
          }
          if (isWorkerToWorkerFetchRestriction(response.status, providerErrorBody)) {
            throw new Error(
              `Review analysis provider request blocked by Cloudflare Worker-to-Worker fetch restriction (error code 1042). Enable the 'global_fetch_strictly_public' compatibility flag on this worker or switch to a service binding.${providerErrorBody ? ` Provider response: ${providerErrorBody}` : ''}`
            );
          }

          const transientStatus = response.status >= 500 || response.status === 429;
          const statusError = new Error(
            transientStatus
              ? `Review analysis provider temporarily unavailable (status ${response.status})${providerErrorBody ? `: ${providerErrorBody}` : ''}`
              : `Review analysis provider request failed with status ${response.status}${providerErrorBody ? `: ${providerErrorBody}` : ''}`
          );

          if (transientStatus && attempt < REVIEW_PROVIDER_MAX_ATTEMPTS) {
            await sleep(REVIEW_PROVIDER_RETRY_DELAY_MS * attempt);
            continue;
          }

          throw statusError;
        }

        const parsed = (await response.json()) as unknown;
        const action = asRecord(parsed).action;
        const validatedAction = this.validateAction(action);
        if (input.forceComplete === true && validatedAction.type !== 'complete') {
          throw new Error('Review analysis finalization step must return type="complete"');
        }
        return validatedAction;
      } catch (error) {
        if (input.abortSignal?.aborted) {
          throw buildProviderAbortError();
        }
        const timeoutLike = isTimeoutLikeError(error);
        const transientNetworkError = error instanceof Error && /fetch failed|network|connection reset|econnreset|socket hang up/i.test(error.message);
        if ((timeoutLike || transientNetworkError) && attempt < REVIEW_PROVIDER_MAX_ATTEMPTS) {
          await sleep(REVIEW_PROVIDER_RETRY_DELAY_MS * attempt);
          continue;

  const maxRetries = parseMaxRetryCount(env.MAX_ATTEMPTS, 3);
  const requestPayload = await getReviewRunRequestPayload(env.DB, reviewId);
  const canRetryWithoutGithubToken = hasLocalCochangeProvenance(requestPayload);
  const rawScopedToken = typeof reviewGithubToken === 'string' && reviewGithubToken.trim() ? reviewGithubToken.trim() : null;
  const scopedGithubToken = rawScopedToken && isValidScopedGithubToken(rawScopedToken) ? rawScopedToken : null;

  if (rawScopedToken && !scopedGithubToken) {
    throw new Error('Scoped GitHub token format is invalid for retry. Expected ghp_* or github_pat_* token.');
  }

  const canRequeue = review.attemptCount <= maxRetries && Boolean(env.REVIEWS_QUEUE) && (scopedGithubToken || canRetryWithoutGithubToken);

  if (canRequeue) {
    await replaceReviewFindings(env.DB, reviewId, []);
    const message = 'Manual recovery requested while review was queued.';
    await updateReviewRunStatus(env.DB, reviewId, 'queued', {
      report: null,
      markdownSummary: null,
      startedAt: null,
      finishedAt: null,
      errorCode: 'retry_scheduled',
      errorMessage: message,
    });
    await appendReviewEvent(env.DB, {
      reviewId,
      eventType: 'review_retry_scheduled',
      payload: {
        attemptCount: review.attemptCount,
        maxRetries,
        reason: 'manual_recovery',
        priorStatus: review.status,
        authMode: scopedGithubToken ? 'scoped_request_token' : 'local_cochange_only',
      },
    });
    await env.REVIEWS_QUEUE?.send(createReviewQueueMessage(reviewId, scopedGithubToken, openrouterApiKey));
    return {
      action: 'requeued',
      review: await getReviewRun(env.DB, reviewId),
    };
  }

  const missingTokenSuffix =
    !scopedGithubToken && !canRetryWithoutGithubToken
      ? ' No retry was scheduled because a fresh scoped GitHub token was not provided.'
      : '';
  const retriesExhaustedSuffix = review.attemptCount > maxRetries ? ' No retry was scheduled because max retry attempts were exhausted.' : '';
  const message = `Manual recovery stopped this review after it appeared stuck in ${review.status} state.${missingTokenSuffix}${retriesExhaustedSuffix}`;
  await updateReviewRunStatus(env.DB, reviewId, 'failed', {
    report: null,
    markdownSummary: null,
    errorCode: 'review_execution_timeout',
    errorMessage: message,
  });
  await appendReviewEvent(env.DB, {
    reviewId,
    eventType: 'review_failed',
    payload: {
      code: 'review_execution_timeout',
      message,
      reason: 'manual_recovery',
    },
  });
  return {
    action: 'failed',
    review: await getReviewRun(env.DB, reviewId),
  };
}

export async function manuallyFailReviewRun(
  env: Env,
  reviewId: string
): Promise<{ action: 'failed'; review: Awaited<ReturnType<typeof getReviewRun>> }> {
  const review = await getReviewRun(env.DB, reviewId);
  if (!review) {
    return { action: 'failed', review: null };
  }

  if (review.status !== 'queued' && review.status !== 'running') {
    throw new Error(`Review is ${review.status}; only queued or running reviews can be failed manually.`);
  }

  const message =
    review.status === 'running'
      ? 'Review was manually marked failed while execution was still in progress. In-flight work may continue until the current attempt ends.'
      : 'Manual fail requested while review was queued.';

  const persisted = await persistManualFailIfCurrent({
    db: env.DB,
    reviewId,
    review: {
      status: review.status,
      attemptCount: review.attemptCount,
    },
    message,
  });
  if (persisted) {
    await appendReviewEvent(env.DB, {
      reviewId,
      eventType: 'review_failed',
      payload: {
        code: 'review_execution_aborted',
        message,
        reason: 'manual_fail',
        priorStatus: review.status,
      },
    });
  }

  return {
    action: 'failed',
    review: await getReviewRun(env.DB, reviewId),
  };
}

