        policyMode,
        lastCheckpoints,
        repoRoot: resolveRepoRootSafe(),
        expectedRepo,
        expectedBranch,
        signal: abortController.signal,
        onEvent: async (event) => {
          if (!streamOpen || abortController.signal.aborted) {
            return;
          }
          try {
            writeSseFrame(response, event);
          } catch {
            streamOpen = false;
            abortController.abort();
          }
        },
      });
